function dateStr(d=gdate()){return d.toLocaleDateString('en-GB',{weekday:'short',day:'2-digit',month:'short',year:'numeric'}).toUpperCase().replace(/,/g,'');}
const seasonStr=()=>`${G.season}/${String(G.season+1).slice(2)}`;
