  flex:{mode:'2',to:.005,vs:{man:.02,zone:-.02,press:.01},fit:ps=>pbTop(ps,p=>p.a.ath,4),pick:o=>o.on.reduce((a,b)=>(b.a.ath+b.a.ins)>(a.a.ath+a.a.ins)?b:a),beats:'man,press'},
