  const prK=1-.1*sk('pr'),nk=isNBA(G.teams[G.user])&&(r.kind==='nl'||r.kind==='nlpo')?(r.kind==='nl'?.4:.7):1;const dbyName=derbyOf(r.h,r.a),dbyK=dbyName?2:1;G.board=clamp(G.board+(won?(wp<.4?3:1.5):-(wp>.6?3:1.5)*prK)*dk*nk*dbyK,0,100);
