function simStep(um){if(typeof pwOpen==='function'&&pwOpen()){while(pwOpen())pwDay();}if(G&&!G.sacked&&G.teams[G.user]&&!seasonOver()&&G.teams[G.user].order.length<5&&typeof fillRoster==='function')fillRoster();const d0=G?G.day:0;const r=simStep0(um);try{if(G&&G.nid-(G.ddN||0)>150)dedupePlayers();}catch(e){}try{apTick();}catch(e){console.error('AP poll',e);}try{if(seasonOver())dpEnsure();}catch(e){console.error('draft return',e);}try{rcTick();}catch(e){console.error('recruiting',e);}try{nbaCal(d0);}catch(e){}try{nlCoachTick();boardMidTick();awExp();scoutWork();if(G.day>=92&&!preOn())retPlan();}catch(e){}if(G&&G.teams[G.user])recoverTo(G.teams[G.user],G.day);shortTick();faTick();faBidTick();clauseTick();ddTick();watchTick();moodTick();roleDev();derbyTick();hypeTick();tenTick();pdTick();eeTick();fanTick();scoutTick();contractTick();midJobTick();try{staffPoachTick();}catch(err){console.error(err);}try{treqTick();}catch(err){console.error(err);}try{rumourTick();}catch(err){console.error(err);}try{feedTick();}catch(err){console.error(err);}pokTick();try{ntTick();}catch(e){}try{nbaAllStarTick();}catch(e){}try{waivTick();}catch(e){}try{nbaHomeTick();nbaAIExtTick();}catch(e){}return r;}
function simStep0(um){
  if(preOn())return preStep(um);
  if(pokUserDue())return pokStep(um);
  if(G.leg==='aq'&&aqOn())return aqUserStep(um);
  if(G.leg==='ec'||(userIsCup()&&userCup()==='ec'&&G.ec&&G.ec.phase!=='done'&&ecUserIn()))return ecUserStep(um);
  if(G.leg==='bcl'||(userIsCup()&&userCup()==='bcl'&&G.bcl&&G.bcl.phase!=='done'&&bclUserIn()))return bclUserStep(um);
  if(G.leg==='fec'||(userIsCup()&&userCup()==='fec'&&G.fec&&G.fec.phase!=='done'&&fecUserIn()))return fecUserStep(um);
  if(userIsKls())G.leg='kls';
  if(userIsBih())G.leg='bih';
  if(userIsNL())G.leg='nl';
  const natLeg=G.leg==='kls'||G.leg==='bih'||(G.leg==='nl'&&(userIs2()||(userIsDom()&&!userIsNL())));
  if(userIsDom()&&!natLeg)G.leg='dom';
  if(userIs2()&&!natLeg)G.leg='dom2';
  const fx=getFixtures(),lbl=stepLabel(),out=[];
  for(const f of fx){const mine=f.h===G.user||f.a===G.user;const m=(mine&&um)?um:new Match(f.h,f.a,{kind:f.kind,neutral:f.neutral}).run();out.push({f,r:applyResult(m,f)});}
  G.lastResults={label:lbl,list:out.map(x=>x.r),dom:G.leg==='dom'};
  if(G.leg==='kls'&&userIsKls()){domBetween();klsAdvance(out);klsUserCatchUp();}
  else if(G.leg==='kls'){domBetween();klsAdvance(out);if(G.kls.phase==='done'||!klsUserIn()){klsFinishSilent();G.leg=userIs2()?'dom2':userIsDom()?'dom':'el';endOrKls();}}
  else if(G.leg==='nl'){domBetween();const L=nlUser();nlAdvance(L,out);if(userIsNL())nlUserCatchUp(L);if(userNBA()){try{nbaStepAI();}catch(e){console.error(e);}}
    // an ABA League 2 club that also plays its national league (MZT, TFT): back to the ABA League 2 next, or on in the national league once that is over
    else if(userIs2()){if(G.dom2&&G.dom2.phase!=='done')G.leg='dom2';else{if(L.phase==='wait')nlStartPO(L);if(!(L.phase==='reg'||(L.phase==='po'&&nlUserIn(L)))){nlFinishSilent(L);G.leg='dom2';endOrKls();}}}
    else if(userIsDom()&&!userIsNL()){if(G.dom&&G.dom.phase!=='done')G.leg='dom';else{if(L.phase==='wait')nlStartPO(L);if(!(L.phase==='reg'||(L.phase==='po'&&nlUserIn(L)))){nlFinishSilent(L);G.leg='dom';endOrKls();}}}
    else if(G.phase!=='done'){G.leg='el';}else if(L.phase==='done'||!nlUserIn(L)){nlFinishSilent(L);G.leg='el';endOrKls();}}
  else if(G.leg==='bih'&&userIsBih()){domBetween();bihAdvance(out);bihUserCatchUp();}
  else if(G.leg==='bih'){domBetween();bihAdvance(out);if(G.bih.phase==='done'||!bihUserIn()){bihFinishSilent();G.leg=userIs2()?'dom2':userIsDom()?'dom':'el';endOrKls();}}
  else if(G.leg==='dom2'){domBetween();dom2Advance(out);dom2UserCatchUp();{const L=nlUser();if(L&&!userIsNL()&&G.leg==='dom2'&&G.dom2.phase!=='done'){if(L.phase==='wait')nlStartPO(L);if(L.phase==='reg'||(L.phase==='po'&&nlUserIn(L)))G.leg='nl';}}}
  else if(G.leg==='dom'){domBetween();domAdvance(out);if(userIsDom())domUserCatchUp();else domNextLeg(false);{const L=nlUser();if(L&&userIsDom()&&!userIsNL()&&G.leg==='dom'&&G.dom.phase!=='done'){if(L.phase==='wait')nlStartPO(L);if(L.phase==='reg'||(L.phase==='po'&&nlUserIn(L)))G.leg='nl';}}}
  else{const wasReg=G.phase==='reg';betweenRounds();advanceStep(out);domAfterEL(wasReg);{const L=nlUser();if(wasReg&&L&&!userIsNL()&&L.phase==='reg'&&G.leg==='el')G.leg='nl';}}
  cupHook();
  if(G.board<=5&&!G.sacked&&!G.ulti&&!seasonOver()){G.sacked=true;}
  save();
  return lbl;
}
// injury risk multiplier by energy before the game: fresh 1x, tired up to 3.5x
const fatigueRisk=e=>e>=80?1:e>=65?1.5:e>=50?2.3:3.5;
function betweenRounds(){
  const reg=G.phase==='reg',tr=G.training,SF=staffFx();
  const rec=22+(tr.focus==='conditioning'?6:0)+({light:6,normal:0,hard:-6})[tr.intensity];
  for(const id in G.players){const p=G.players[id];
    if(p.tid==null){if(p.inj>0)p.inj--;p.energy=clamp(p.energy+22,0,100);}
    const devL=!!(p.loan&&p.loan.dev);
    if((p.tid==null&&!devL)||p.age>29)continue;
    const user=p.tid===G.user,focus=user?tr.focus:'balanced',mult=(user?({light:.6,normal:1,hard:1.5})[tr.intensity]*SF.train:devL?1.15:1)*(p.age<=25?devK(p):1);
    const gap=p.pot-p.o,ch=(p.age<=22?.25:p.age<=25?.15:.07)*mult*(gap>0?1:.15)*(G.gdr>.15?clamp(1-G.gdr*.35,.5,1):1);
    if(Math.random()<ch){const k=Math.random()<.65?pick(FOCUSATTR[focus]):pick(ATTR);if(p.a[k]<99){const old=p.o;p.a[k]++;upd(p);if(user){G.trainLog.unshift({pid:p.id,k,o:p.o,up:p.o>old,d:dateStr()});if(G.trainLog.length>30)G.trainLog.length=30;}}}
  }
  if(reg){const w=Math.round((wageBill(G.user)+loanCost())/G.schedule.length),sw=Math.round(staffWages(G.user)/G.schedule.length),s=Math.round(G.fin.sponsor/G.schedule.length);const wf=Math.min(G.fin.wfund||0,w);G.fin.wfund=(G.fin.wfund||0)-wf;G.fin.bal+=s-(w-wf)-sw;G.fin.season.wages+=w;G.fin.season.staff=(G.fin.season.staff||0)+sw;G.fin.season.spon+=s;}
  aiCoachChanges();if(reg){ensureFinance();aiFinanceRound();userFinanceRound();}
  if(reg)promiseCheck();
  if(reg)loanRound();
  if(reg)sponsorRound();
  if(reg&&G.dom2&&G.dom2.phase!=='done'&&!userIs2()&&G.round%2===1)dom2SilentStep();
  if(reg&&G.kls&&G.kls.phase==='reg'&&!userIsKls())klsSilentStep();
  if(reg&&G.bih&&G.bih.phase==='reg'&&!userIsBih())bihSilentStep();
  nlTickAll();
  G.fin.hist.push({l:stepLabel(),bal:G.fin.bal});if(G.fin.hist.length>80)G.fin.hist.shift();
  for(const t of G.teams)if(t.id!==G.user&&!(userNBA()&&isNBA(t))){t.order=autoOrder(t.order);aiFix(t);}if(!userNBA()){try{nbaPlanTick();}catch(e){}aiTradeIdea();}
  if(reg){
    if(!userNBA()&&!isCol(G.teams[G.user]))for(const pid of G.listed)if(Math.random()<.3){const p=G.players[pid];const b=pick(ELT().filter(t=>t.id!==G.user&&teamFinState(t.id)==='ok'));if(!b)continue;const fee=r10k(value(p)*rf(.75,1.15));
      msg(b.name,`Offer for ${pname(p)}`,`${b.name} would like to sign ${pname(p)} (${p.pos}, ${p.age}, OVR ${p.o}) and offer a transfer fee of ${eur(fee)}.`,'offer',{pid,tid:b.id,fee});}
    if(!userNBA()&&!isCol(G.teams[G.user])&&Math.random()<.07){const top=roster(G.user).filter(p=>!p.loan).sort((a,b)=>b.o-a.o).slice(0,4);const p=pick(top);const b=pick(ELT().filter(t=>t.id!==G.user&&t.rep>=G.teams[G.user].rep-3&&teamFinState(t.id)==='ok'));
      if(p&&b){const fee=r10k(value(p)*rf(1.05,1.45));msg(b.name,`Bid for ${pname(p)}`,`${b.name} have made an unsolicited bid of ${eur(fee)} for ${pname(p)}. Their sporting director is open to talks about the fee.`,'offer',{pid:p.id,tid:b.id,fee});}}
    if(G.round===29){const ex=roster(G.user).filter(p=>p.yrs<=1);if(ex.length)msg('Sporting Director','Contracts expiring this summer',`These contracts end after the season: ${ex.map(p=>`${pname(p)} (OVR ${p.o})`).join(', ')}. Open a player's profile in Squad to offer an extension, or let them leave for free.`,'fin');}
  }
  G.day+=nlUser()&&nlUser().code==='NCAA'&&userIsNL()&&nlUser().phase!=='done'?(nlUser().phase==='reg'?3:1):nlUser()&&nlUser().code==='JPN'&&userIsNL()&&nlUser().phase!=='done'?(nlUser().phase==='reg'?2:1):nlUser()&&nlUser().code==='AUS'&&userIsNL()&&nlUser().phase!=='done'?(nlUser().phase==='reg'?2:3):G.phase==='reg'?((domPlaysUser()&&G.dom.phase==='reg')||(nlUser()&&!userIsNL()&&nlUser().phase==='reg')?3:5):G.phase==='qf'?3:G.phase==='f4'?2:3;
}
// AI clubs sign good free agents: each player goes to a club whose level fits him and where he would play

/* ===================== Transfer market: money, home pull, promotion and relegation ===================== */
// What clubs in each league can pay, relative to a EuroLeague club (1). Free agents lean towards the money and towards home;
// the level filter in aiFASign still decides which clubs are realistic for them.
const MKPAY={SFB:.3,CZN:.4,LPT:.45,NBB:.4,KSL:.5,IBL:.35,BLS:.25,LNA:.4,BSN:.45,RDO:.35,TPB:.45,PLG:.45,SUI:.2,VTB:.7,EL:1,NBA:2.2,GL:.14,CBA:1.05,JPN:.75,ACB:.75,BSL:.8,LBA:.6,GBL:.6,ISL:.55,BBL:.55,LNB:.55,ABA:.45,LKL:.45,AUS:.5,QBL:.5,LBL:.45,PLK:.32,BNX:.3,ROU:.25,PBA:.3,GEO:.2,
  CUP:.38,KLS:.2,BIH:.1,ABA2:.15,AUT:.2,GBR:.2,SKL:.2,CGL:.2,CRL:.2,KOS:.18,MKD:.15,NZL:.2,PF:.22,A2:.18,EL2:.2,PROA:.18,TBL:.22,LL:.18,GEL:.12,PML:.08,PROB:.08,SBN:.07,PRD:.08,RL:.03};
const payOf=t=>{const d=t.dom||'EL';return MKPAY[d]!=null?MKPAY[d]:.25;};
function mktW(p,t){const lb=G.lnow&&G.lref&&G.lnow[t.dom||'EL']!=null&&G.lnow[t.dom||'EL']<G.lref[t.dom||'EL']-1.5?1.6:1,pay=Math.pow(payOf(t),.75)*lb,home=p.nat===t.nat?1.9:1,pr=G.prom&&G.prom.y===G.season&&G.prom.up.includes(t.id)?1.6:1,gl=t.dom==='GL'?(p.age<=25?(p.nat==='USA'?1:.4):.08):1;return pay*home*pr*gl;}
// clubs that went up or down this summer
function prRec(id,dir){const P=G.prom&&G.prom.y===G.season?G.prom:(G.prom={y:G.season,up:[],down:[]});(dir==='up'?P.up:P.down).push(id);}
function prMarket(){const P=G.prom;if(!P||P.y!==G.season)return;const out=[];
  const lvOf=code=>{const ids=G.teams.filter(x=>x.dom===code&&!P.down.includes(x.id)&&!P.up.includes(x.id)).map(x=>x.id);return ids.length?avg(ids.map(i=>teamLevel(G.teams[i]))):60;};
  for(const id of P.down){const t=G.teams[id];if(!t||t.id===G.user||!t.dom)continue;t.rep=Math.max(30,(t.rep||60)-3);const lv=lvOf(t.dom);
    // relegation clauses: the players who are too good for the lower league leave, the imports first
    const ps=roster(t.id).filter(p=>!p.loan).sort((a,b)=>b.o-a.o);let n=0;
    for(const p of ps){if(n>=5)break;const gap=p.o-lv;if(gap<4)continue;if(Math.random()<clamp(.25+gap*.07+(p.nat!==t.nat?.15:0),0,.9)){out.push(`${pname(p)} (${t.short})`);toFA(p);p.sal=salaryFor(p);n++;}}}
  for(const id of P.up){const t=G.teams[id];if(!t||t.id===G.user)continue;t.rep=Math.min(95,(t.rep||50)+3);}
  aiFASign(.85);
  for(const t of G.teams)if(t.id!==G.user&&(P.up.includes(t.id)||P.down.includes(t.id))){aiFix(t);t.order=autoOrder(t.order);}
  if(out.length)msg('Transfer News','Relegation exodus',`After going down, clubs lost players with relegation clauses: ${out.slice(0,10).join(', ')}${out.length>10?` and ${out.length-10} more`:''}.`);}
// the summer's biggest moves between leagues, for the news feed
function mktDigest(snap){const lg=t=>G.teams[t].dom||'EL',nm=c=>(NLCFG[c]&&NLCFG[c].name)||({EL:'EuroLeague',CUP:'EuroCup / BCL',ABA:'ABA League',ABA2:'ABA League 2',KLS:'KLS',BIH:'Prvenstvo BiH'})[c]||c;
  const mv=[];for(const p of Object.values(G.players)){const s0=snap[p.id];if(!s0||p.tid==null||p.tid===s0[0]||p.tid===G.user)continue;const l0=s0[1],l1=lg(p.tid);if(l0===l1||p.o<70)continue;mv.push({p,l0,l1,from:s0[2]});}
  if(!mv.length)return;mv.sort((a,b)=>b.p.o-a.p.o);
  msg('Transfer News','Summer transfer market',mv.slice(0,12).map(x=>`${pname(x.p)} (${x.p.o}): ${x.from} → ${G.teams[x.p.tid].name} (${nm(x.l1)})`).join('. ')+'.');}
// an AI club keeps a player whose deal ends: locals and veterans usually stay, imports and players who outgrew the club test the market
function aiStay(p,t){const gap=p.o-teamLevel(t);let s=.65;if(p.nat!==t.nat)s-=.15;else s+=.12;if(gap>=5)s-=.2;else if(gap<=-6)s-=.1;if(p.age>=31&&p.nat===t.nat)s+=.1;if(payOf(t)<.3&&p.o>=72)s-=.15;if((t.rep||0)>=85&&!t.dom)s+=.12;return clamp(s,.2,.85);}

/* ===================== Long-term stability ===================== */
// Each league keeps the level it had at the start of the career (G.lref, average club level). AI clubs sign players up to that level
// plus a margin that grows with the club's reputation, so a league cannot ratchet itself up season after season.
function lrefEnsure(){if(G.lref)return;G.lref={};G.lrep={};const by={};for(const t of G.teams){if(!t.order||t.order.length<8||t.dom==='GONE'||t.dom==='FOUND')continue;const c=t.dom||'EL';(by[c]=by[c]||[]).push(t);}
  if(G.gref==null)G.gref=+gAvg().toFixed(2);for(const [c,ts] of Object.entries(by)){G.lref[c]=+avg(ts.map(t=>teamLevel(t))).toFixed(1);G.lrep[c]=+avg(ts.map(t=>t.rep||60)).toFixed(1);}}
function gAvg(){const on=Object.values(G.players).filter(p=>p.tid!=null&&!(G.teams[p.tid]&&G.teams[p.tid].dom==='NCAA'));return on.length?avg(on.map(p=>p.o)):60;}
function lforEnsure(){if(G.lfor)return;G.lfor={};const by={};for(const t of G.teams){if(!t.order||t.order.length<8||!t.dom||t.dom==='GONE'||t.dom==='NBA'||t.dom==='NCAA')continue;const f=roster(t.id).filter(p=>p.nat!==t.nat).sort((a,b)=>b.o-a.o)[0];if(f)(by[t.dom]=by[t.dom]||[]).push(f.o);}for(const c in by)if(by[c].length>=4&&FORRULE[c]){const v=avg(by[c]);if(G.lref&&G.lref[c]!=null&&v-G.lref[c]>5)G.lfor[c]=+v.toFixed(1);}}
function lcapP(t,p){const b=lcap(t);if(!p||p.nat===t.nat||!t.dom)return b;lforEnsure();const f=G.lfor[t.dom];return f!=null?Math.max(b,f+2+clamp(((t.rep||60)-(G.lrep[t.dom]||60))*.25,-3,4)):b;}
function lgDrift(p){if(p.tid==null||!G.lnow||!G.lref)return 0;const t=G.teams[p.tid],c=t&&(t.dom||'EL');if(!c||c==='NBA'||c==='NCAA'||G.lnow[c]==null||G.lref[c]==null)return 0;const d=G.lnow[c]-G.lref[c];
  if(d<-1.5&&p.age<=29)return Math.random()<clamp(-d*.12,0,.6)?1:0;if(d>2&&p.age>=24&&p.o<84)return Math.random()<clamp(d*.08,0,.5)?-1:0;return 0;}
const impTop=(t,p)=>{if(!t.dom||p.nat===t.nat)return 0;lforEnsure();const f=G.lfor[t.dom];return f!=null?f+3:0;};
function lcap(t){if(!G.lref)lrefEnsure();const c=t.dom||'EL';if(c==='NBA'||c==='NCAA'||G.lref[c]==null)return 99;return G.lref[c]+5+clamp(((t.rep||60)-(G.lrep[c]||60))*.25,-4,6);}
// an empty value does not need to be stored for every player
function slimPlayers(){for(const p of Object.values(G.players)){for(const k of ['dst','est','kst'])if(p[k]&&!p[k].gp)delete p[k];for(const k of ['fragile','rm','ld','dvm','dvt'])if(p[k]==null||p[k]===0)delete p[k];}}

/* ===================== Finances of domestic AI clubs ===================== */
// Clubs outside the EuroLeague keep a simple budget (t.dfin): revenue that roughly covers wages and staff, moved by results,
// promotion and relegation, sponsors coming and going. Half a season's result is booked in winter, half in summer.
// Strain: they sell more readily. Crisis: no free-agent signings, the most overpaid players are released. Insolvent: an owner or
// the city may rescue the club; otherwise it goes bankrupt: forced relegation where a lower division exists, the best-paid players
// leave and the club starts again without debt.
const dfinOK=t=>t&&t.id!==G.user&&!t.fin&&t.dom&&!['NBA','GL','NCAA','GONE','FOUND'].includes(t.dom)&&t.order&&t.order.length;
function dfinEnsure(){for(const t of G.teams){if(t.dfin||!dfinOK(t))continue;const W=teamCosts(t.id);t.dfin={bal:r10k(W*rf(-.04,.25)),rev:Math.round(W*rf(1.01,1.09)),own:+rf(.15,.8).toFixed(2),st:'ok'};}}
const dfinMine=t=>{const U=G.teams[G.user];return t.dom===U.dom||(t.rep||0)>=72||Object.values(G.nl||{}).some(L=>L&&L.ids&&L.ids.includes(G.user)&&L.ids.includes(t.id));};
function dfinBook(half){dfinEnsure();for(const t of G.teams){const F=t.dfin;if(!F||!dfinOK(t))continue;const W=teamCosts(t.id);F.bal=Math.round(F.bal+(F.rev-W)*half);F.st=finState(F.bal,W);}}
function dfinRank(t){const L=Object.values(G.nl||{}).find(L=>L&&L.ids&&L.ids.includes(t.id));if(!L)return null;const r=nlRank(L,t.id),n=L.ids.length;return {r,n,champ:L.champ===t.id};}
function dfinSummer(){dfinEnsure();const ev=[];
  for(const t of G.teams){const F=t.dfin;if(!F||!dfinOK(t))continue;const W=teamCosts(t.id);
    // revenue drifts toward the club's costs, results and divisions move it
    let k=rf(.98,1.07);const rk=G.qprev&&G.qprev[t.dom]?G.qprev[t.dom].indexOf(t.id):-1,n=G.qprev&&G.qprev[t.dom]?G.qprev[t.dom].length:0;
    if(rk===0)k*=1.06;else if(rk>0&&rk<3)k*=1.03;else if(n&&rk>=n-3)k*=.96;
    F.rev=Math.round(.3*F.rev+.7*W*k*(F.st==='ok'?1:1.07));
    if(G.prom&&G.prom.y===G.season){if(G.prom.down.includes(t.id))F.rev=Math.round(F.rev*.78);if(G.prom.up.includes(t.id))F.rev=Math.round(F.rev*1.18);}
    if(Math.random()<.03){F.rev=Math.round(F.rev*rf(.85,.93));if(dfinMine(t))ev.push(`${t.name} lost a main sponsor`);}
    if(Math.random()<.03){F.bal+=r10k(W*rf(.06,.15));}
    F.st=finState(F.bal,W);
    if(F.st==='crisis'||F.st==='admin'){
      // wage cuts: the most overpaid players go
      const ps=roster(t.id).filter(p=>!p.loan).sort((a,b)=>b.sal/Math.max(1,value(b))-a.sal/Math.max(1,value(a)));let cut=0;
      for(const p of ps.slice(0,F.st==='admin'?2:1)){if(t.order.length<=12)break;cut+=p.sal;toFA(p);p.sal=salaryFor(p);}
      if(cut&&dfinMine(t))ev.push(`${t.name} cut costs and released players`);t.rep=Math.max(30,(t.rep||50)-1);}
    if(F.st==='admin'){
      if(Math.random()<.25+F.own*.4){const x=r10k(W*rf(.25,.5));F.bal+=x;F.st=finState(F.bal,W);F.own=Math.max(.1,F.own-.1);if(dfinMine(t))news(`${t.name} rescued`,`The owners of ${t.name} put in ${eur(x)} to save the club from insolvency.`);}
      else dfinBankrupt(t,ev);}}
  for(const t of G.teams)if(t.dfin&&dfinOK(t)&&t.order.length<12){aiFix(t);t.order=autoOrder(t.order);}
  if(ev.length)news('Club finances',ev.slice(0,12).join('. ')+'.');}
function dfinBankrupt(t,ev){const to=null,name=t.name,from=t.dom;
  const ps=roster(t.id).filter(p=>!p.loan).sort((a,b)=>b.sal-a.sal);for(const p of ps.slice(0,3)){toFA(p);p.sal=salaryFor(p);}
  t.rep=Math.max(25,(t.rep||50)-6);
  const W=teamCosts(t.id);t.dfin={bal:0,rev:Math.round(W*rf(.98,1.04)),own:+rf(.2,.6).toFixed(2),st:'ok'};t.dbk=G.season;
  news(`${name} declared bankrupt`,`${name} could not pay their debts.${to?` The club restarts in the ${NLCFG[to].name}.`:' The club restarts with a new, smaller budget.'} The best-paid players have left.`);
  if(G.teams[G.user]&&G.teams[G.user].dom===from)msg('League Office',`${name} bankrupt`,`${name} are bankrupt${to?` and drop to the ${NLCFG[to].name}`:''}. Their players are on the market.`,'board');}
// retirement: a gradual chance from 33 on; good players play longer, weak and unsigned veterans stop sooner
function retireP(p){const a=p.age;if(a<33)return 0;if(a>=47)return 1;const B={33:.04,34:.09,35:.18,36:.26,37:.34,38:.43,39:.52,40:.62,41:.72,42:.8,43:.88};let r=B[a]!=null?B[a]:.95;
  r*=p.o>=80?.6:p.o>=75?.8:p.o<50?1.6:1;if(p.tid==null&&!p.ntOnly)r*=1.8;return clamp(r,0,1);}

/* ===================== Moving money between transfer and wage budget ===================== */
// For the current season the user can move transfer money into the wage budget, or give up unused wage room for transfer money.
// Wages are paid each regular-season round, so only the part of the season still to come counts: transfer money moved into wages
// goes into a fund that pays wages first; wage room given up returns only the share of the season that is left. Next summer the
// board sets the budgets again (the moved amount is taken back out of the wage budget).
function budLeft(){if(preOn())return 1;if(G.phase!=='reg'||!G.schedule||!G.schedule.length)return 0;return clamp(1-G.round/G.schedule.length,0,1);}
const budStep=()=>Math.max(10000,r10k(G.fin.wageBudget*.02));
const budRoom=()=>Math.max(0,G.fin.wageBudget-wageBill(G.user));
function budMove(dir,amt){if(userNBA())return 'NBA clubs work with the salary cap.';const f=budLeft();if(f<=0)return 'Wages for this season have been paid: you can move money again next season.';
  amt=amt||budStep();
  if(dir==='w'){if(userFinState()!=='ok')return 'Not while the club is in debt.';const cost=r10k(amt*f);if(G.fin.bal<cost)return `You need ${eur(cost)} in the transfer budget.`;
    G.fin.bal-=cost;G.fin.wfund=(G.fin.wfund||0)+cost;G.fin.wageBudget+=amt;G.fin.wconv=(G.fin.wconv||0)+amt;save();return null;}
  if(budRoom()<amt)return `Only ${eur(budRoom())} of the wage budget is unused.`;const back=r10k(amt*f);
  G.fin.wageBudget-=amt;G.fin.wconv=(G.fin.wconv||0)-amt;const fromFund=Math.min(G.fin.wfund||0,back);G.fin.wfund=(G.fin.wfund||0)-fromFund;G.fin.bal+=back;save();return null;}

// Players decide at the start of a season whether it is their last (p.retAt = that season), so the user knows before contract talks.
// Only they retire next summer; a player with years left on his deal is less likely to stop. Old saves without plans use the old roll once.
function retPlan(){if(!G||G.retV===G.season)return;G.retV=G.season;const mine=[];// called once a season on 1 January (game day 92)
  const last=[];for(const p of Object.values(G.players)){if(p.oneMore===G.season){p.retAt=G.season;p.retTry=G.season;delete p.oneMore;if(p.tid===G.user)last.push(pname(p));continue;}if(p.yth!=null||p.retAt===G.season||p.extS===G.season||(p.tid===G.user&&p.newAt===G.season))continue;if(p.retAt!=null&&p.retAt<G.season)delete p.retAt;
    const r=retireP({age:p.age+1,o:p.o,tid:p.tid})*(p.yrs>1?.4:1);if(Math.random()<r){p.retAt=G.season;if(p.tid===G.user)mine.push(p);}}
  for(const p of mine)msg(pname(p),'This is my last season',`Coach, I have thought about it for a long time: this season will be my last as a player. I will not sign a new contract.`,'retire',{pid:p.id});
  if(last.length)msg('Sporting Director','Farewell season',`As agreed a year ago, this is the last season of ${last.join(', ')}.`,'fin');}
function aiFASign(rate){if(!G||!G.fa.length)return 0;let n=0;
  const clubs=G.teams.filter(t=>t.id!==G.user&&!t.ntTemp&&t.dom!=='NCAA'&&t.dom!=='GONE'&&t.dom!=='FOUND'&&!t.bankrupt&&!(t.dfin&&(t.dfin.st==='crisis'||t.dfin.st==='admin')&&t.order.length>=12)).map(t=>{const ps=roster(t.id).slice().sort((a,b)=>b.o-a.o);return {t,lv:teamLevel(t),tenth:ps[9]?ps[9].o:0,n:ps.length,R:ruleOfTeam(t),cap:lcap(t)};});
  const fas=G.fa.map(i=>G.players[i]).filter(p=>p&&!p.nfa&&!p.portal&&p.o>=58&&p.yth==null&&!(p.loan&&p.loan.dev)&&!(G.faBid&&G.faBid[p.id])).sort((a,b)=>b.o-a.o);
  for(const p of fas){if(Math.random()>rate)continue;
    // he prefers clubs near his level, but a step or two down (for less money) is also on the table
    // how far down he goes: stars and players in their prime stay near their level, veterans and long-unsigned players go further
    const down=(p.o>=78?5:p.age<=29?7:p.age<=32?10:13)+(G.phase==='reg'?Math.min(4,(G.round||0)/6):0);
    const fit=clubs.filter(c=>c.n<17&&p.o>c.tenth+2&&p.o>=c.lv-7&&p.o<=Math.max(c.lv+down,impTop(c.t,p))&&p.o<=(p.nat!==c.t.nat?lcapP(c.t,p):c.cap)&&forRoom(c.t,p,c.R));if(!fit.length)continue;
    const w=c=>{const gap=p.o-c.lv;return (gap<=4?3:gap<=8?1.4:.6)*(1+c.t.rep/100)*mktW(p,c.t);};let r=Math.random()*fit.reduce((s,c)=>s+w(c),0),c=fit[0];for(const x of fit){r-=w(x);if(r<=0){c=x;break;}}const t=c.t;
    let want=Math.max(10000,Math.round(salaryFor(p,t)*Math.max(.55,1-(Math.max(0,p.o-c.lv-4))*.05)/5000)*5000);
    if(isNBA(t)){const C=capv(),P=nbaPayroll(t.id);if(P+want>C.cap){if(t.mle!==G.season&&P+Math.min(want,C.ntmle)<=C.ap1){want=Math.min(want,C.ntmle);t.mle=G.season;}else if(t.mle!==G.season&&P+Math.min(want,C.tmle)<=C.ap2){want=Math.min(want,C.tmle);t.mle=G.season;}else if(want>C.min*2.5&&Math.random()<.7)continue;else want=C.min;}}
    G.fa=G.fa.filter(i=>i!==p.id);markNew(p,t);p.sal=want;p.yrs=p.age>=32?1:rnd(1,3);join(p,t);t.order=autoOrder(t.order);c.n++;
    const ps=roster(t.id).slice().sort((a,b)=>b.o-a.o);c.tenth=ps[9]?ps[9].o:0;n++;
    const ex=(G.exp||[]).some(x=>x.id===p.id);
    if(p.o>=74||ex)news(`${pname(p)} signs for ${t.name}`,`Free agent ${pname(p)}${p.last?` (last at ${p.last})`:''} has joined ${t.name} on a ${p.yrs}-year deal.`);
    if(c.n>16){const w=roster(t.id).filter(q=>!q.loan&&q.id!==p.id).sort((a,b)=>a.o-b.o)[0];if(w){toFA(w);c.n--;}}}
  return n;}
function aiFix(t){
  if(isNBA(t)&&G.nfa)return;if(t.dom==='NCAA')return;
  while(t.order.length<12&&G.fa.length){const best=G.fa.map(i=>G.players[i]).filter(p=>!p.nfa&&!p.prospect&&(!t.dom||p.o<=t.rep+1)).sort((a,b)=>b.o-a.o)[0];if(!best){join(genPlayer(isNBA(t)?rnd(72,77):t.rep-10+rnd(-3,3),pick(POS),t.nat,rnd(19,30)),t);continue;}G.fa=G.fa.filter(i=>i!==best.id);best.sal=isNBA(t)&&nbaPayroll(t.id)+salaryFor(best,t)>capv().cap?capv().min:salaryFor(best,t);best.yrs=rnd(1,2);join(best,t);markNew(best,t);}
  while(t.order.length>20){const worst=roster(t.id).filter(p=>!p.loan).sort((a,b)=>a.o-b.o)[0];if(!worst)break;toFA(worst);}
}
function prize(amount,why){G.fin.bal+=amount;G.fin.season.prize+=amount;if(/Playoff qualification/.test(why))sponsorBonus('po');if(/Final Four qualification/.test(why))sponsorBonus('f4');if(/champions/.test(why))sponsorBonus('title');msg('Euroleague',why,`The club receives ${eur(amount)} in prize money.`,'fin');}
function winnerOf(out,ref){const x=out.find(o=>o.f.ref===ref);return x.r.hs>x.r.as?x.r.h:x.r.a;}
function loserOf(out,ref){const x=out.find(o=>o.f.ref===ref);return x.r.hs>x.r.as?x.r.a:x.r.h;}
function advanceStep(out){
  const U=G.user,po=G.po,u=G.uRes;
  switch(G.phase){
    case 'reg':G.round++;aiFASign(.06);if(G.round===Math.floor(G.schedule.length/2)){try{dfinBook(.5);}catch(e){}try{aiTransfers('winter');}catch(e){}}if(G.round>=G.schedule.length)startPlayIn();break;
    case 'pi1':{po.seeds[6]=winnerOf(out,'a');po.pi.c={h:loserOf(out,'a'),a:winnerOf(out,'b')};
      if(po.seeds[6]===U){u.qf=true;prize(500000,'Playoff qualification');}
      if(loserOf(out,'b')===U)msg('Assistant Coach','Our season is over','We lost the Play-In game. Time to plan for next season.','staff');
      G.phase='pi2';break;}
    case 'pi2':{po.seeds[7]=winnerOf(out,'c');
      if(po.seeds[7]===U){u.qf=true;prize(500000,'Playoff qualification');}else if(po.pi.c.h===U||po.pi.c.a===U)msg('Assistant Coach','Our season is over','We fell short in the final Play-In game.','staff');
      po.qf=[[0,7],[1,6],[2,5],[3,4]].map(([i,j])=>({hi:po.seeds[i],lo:po.seeds[j],wh:0,wl:0,n:0,win:null}));G.phase='qf';break;}
    case 'qf':{for(const o of out){const s=po.qf[o.f.ref];const w=o.r.hs>o.r.as?o.r.h:o.r.a;if(w===s.hi)s.wh++;else s.wl++;s.n++;if(s.wh===3)s.win=s.hi;if(s.wl===3)s.win=s.lo;
        if(s.win!=null&&(s.hi===U||s.lo===U)){if(s.win===U){u.f4=true;prize(1000000,'Final Four qualification');}else msg('Assistant Coach','Eliminated in the playoffs',`We lost the series ${Math.max(s.wh,s.wl)}\u2013${Math.min(s.wh,s.wl)}.`,'staff');}}
      if(po.qf.every(s=>s.win!=null)){po.sf=[{h:po.qf[0].win,a:po.qf[3].win},{h:po.qf[1].win,a:po.qf[2].win}];G.phase='f4';}break;}
    case 'f4':{po.sfw=[winnerOf(out,0),winnerOf(out,1)];po.fin={h:po.sfw[0],a:po.sfw[1]};if(po.fin.h===U||po.fin.a===U){u.fin=true;prize(750000,'Euroleague Final reached');}G.phase='fin';break;}
    case 'fin':{po.champ=winnerOf(out,'fin');if(po.champ===U){u.champ=true;prize(1500000,'Euroleague champions!');}G.phase='done';break;}
  }
}
function startPlayIn(){
  const st=standings();G.po={seeds:st.slice(0,10).map(t=>t.id),pi:{a:{h:st[6].id,a:st[7].id},b:{h:st[8].id,a:st[9].id}},qf:null,sf:null,fin:null,champ:null};
  if(userNotEL()){G.uRes={};G.phase='pi1';return;}
  const r=rankOf(G.user);G.uRes={rank:r,pi:r>=7&&r<=10,qf:r<=6};
  if(r<=6){prize(500000,'Playoff qualification');msg('Club President','Straight into the playoffs',`We finished ${ordn(r)} and go directly to the quarter-finals. Well done.`,'board');}
  else if(r<=10)msg('Assistant Coach','Play-In ahead',`We finished ${ordn(r)}. We must win the Play-In to reach the playoffs.`,'staff');
  else msg('Club President','Regular season finished',`We finished ${ordn(r)} and missed the post-season.`,'board');
  G.phase='pi1';
}
function finishLabel(u){return u.champ?'Champions':u.fin?'Runner-up':u.f4?'Final Four':u.qf?'Quarter-finals':u.pi?'Play-In':'Regular season';}
function seasonEnd(){
  if(aqOn()&&(G.aq.aba===G.user||G.aq.a2===G.user)){if(G.leg!=='aq')G.aq.leg=G.leg;G.leg='aq';return;}
  if(G.ec&&G.ec.phase!=='done')ecFinishSilent();if(G.bcl&&G.bcl.phase!=='done')bclFinishSilent();if(G.fec&&G.fec.phase!=='done')fecFinishSilent();
  if(userIsCup())return seasonEndCup();
  if(userIsNL())return seasonEndNL();
  if(userIsKls())return seasonEndKls();
  if(userIsBih())return seasonEndBih();
  if(userIs2())return seasonEndDom2();
  if(userIsDom())return seasonEndDom();
  const u=G.uRes,met={f4:!!u.f4,qf:!!u.qf,pi:u.rank<=10,top14:u.rank<=14}[G.obj];
  G.board=clamp(G.board+(met?20:-25)+(u.champ?15:0),0,100);
  seasonFinanceCheck();resolveInterims();
  const D=G.dom,dres=D&&D.ids.includes(G.user)?domFinish():null;
  const NU=nlUser();if(NU&&NU.phase==='done'){const nm=nlObjMet(NU);G.board=clamp(G.board+(nm?6:-8)+(NU.champ===G.user?6:0),0,100);}
  if(dres){const dm=domObjMet();G.board=clamp(G.board+(dm?6:-8)+(D.champ===G.user?6:0),0,100);}
  G.history.unshift({season:seasonStr(),champName:G.teams[G.po.champ].name,champ:G.po.champ,rank:u.rank,finish:finishLabel(u),obj:G.obj,objText:OBJ[G.obj],met,dom:D&&D.champ!=null&&dres?{name:D.name,champ:D.champ,champName:G.teams[D.champ].name,finish:dres}:NU&&NU.champ!=null?{name:NLCFG[NU.code].name,champ:NU.champ,champName:G.teams[NU.champ].name,finish:nlFinish(NU)}:D&&D.champ!=null?{name:D.name,champ:D.champ,champName:G.teams[D.champ].name,finish:dres}:null});
  msg('Club President',met?'Objective achieved':'Objective missed',met?`You delivered: ${objText().toLowerCase()}. The board's confidence in you has grown.`:`The target was to ${objText().toLowerCase()}. The board expects a clear improvement next season.`,'board');
  
  jobOfferRound(met);
}
// shirt numbers stay unique within a club (a rating fix or a real roster sync can bring a double); potential is never below the rating
function normSquads(){for(const t of G.teams){if(!t.order||t.dom==='GONE')continue;const used=new Set();for(const id of t.order){const p=G.players[id];if(!p)continue;if(p.no!=null&&p.no>=0&&used.has(p.no)){const n=NUMS.find(x=>!used.has(x));p.no=n==null?rnd(60,98):n;}used.add(p.no);}}
  for(const id in G.players){const p=G.players[id];if(p&&p.pot!=null&&p.o>p.pot)p.pot=p.o;}}
// PBA Rookie Draft (own data G.pdraft, separate from the NBA draft). The real Season 51 draft is in January 2027; the game's PBA season (one
// conference) ends in December, so the draft is held right after the Finals, at the latest on 20 January (game day 111).
// Order: reverse of last season's final ranking (the real draft weighs all three conferences; the game plays one); no lottery. Rounds go on
// until every club passes (max 6). First round 3-year rookie deals, second round 2 years, later 1 year. The first draft uses the projected
// real order with the traded picks and the real prospects from the 2027 mock drafts (All-Star Magazine, Aug 2026; ESPN, Sep 2026).
